 clearTimeout(m.wd);m.wd=setTimeout(()=>{if(g.phase==='battle'&&players[g.order[g.turn]]===m){if(g.pend){clearTimeout(g.pend.timer);g.pend=null}next();bc()}},25000); // страховка: ход монстра не может зависнуть
